-- =========================================================
-- FASIH DATABASE
-- VERSION 1.1
-- CUSTOM LOGIN - TANPA SUPABASE AUTH
-- =========================================================

-- =========================================================
-- 0. EXTENSION
-- =========================================================

create extension if not exists pgcrypto;


-- =========================================================
-- 1. FUNCTION updated_at
-- =========================================================

create or replace function public.fasih_set_updated_at()
returns trigger
language plpgsql
as $$
begin
    new.updated_at = now();
    return new;
end;
$$;


-- =========================================================
-- 2. MASTER PETUGAS
-- =========================================================

create table if not exists public.fasih_officers (
    id uuid primary key default gen_random_uuid(),

    username text,
    name text not null,

    officer_role text not null
        check (officer_role in ('pencacah', 'pengawas')),

    is_active boolean not null default true,

    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

create index if not exists idx_fasih_officers_role
    on public.fasih_officers(officer_role);

create index if not exists idx_fasih_officers_username
    on public.fasih_officers(username);


-- =========================================================
-- 3. USER / AKUN FASIH
-- =========================================================
-- Tidak menggunakan Supabase Auth.
-- Password disimpan dalam bentuk HASH, bukan plaintext.

create table if not exists public.fasih_users (
    id uuid primary key default gen_random_uuid(),

    officer_id uuid
        references public.fasih_officers(id)
        on delete set null,

    username text not null,

    password_hash text not null,

    name text not null,

    role text not null
        check (role in ('admin', 'viewer')),

    is_active boolean not null default true,

    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),

    constraint fasih_users_username_unique
        unique (username)
);

create index if not exists idx_fasih_users_officer
    on public.fasih_users(officer_id);


-- =========================================================
-- 4. SESSION LOGIN
-- =========================================================

create table if not exists public.fasih_sessions (
    id uuid primary key default gen_random_uuid(),

    user_id uuid not null
        references public.fasih_users(id)
        on delete cascade,

    session_token text not null unique,

    expires_at timestamptz not null,

    created_at timestamptz not null default now()
);

create index if not exists idx_fasih_sessions_user
    on public.fasih_sessions(user_id);

create index if not exists idx_fasih_sessions_token
    on public.fasih_sessions(session_token);

create index if not exists idx_fasih_sessions_expires
    on public.fasih_sessions(expires_at);


-- =========================================================
-- 5. MASTER WILAYAH
-- =========================================================

create table if not exists public.fasih_regions (
    id uuid primary key default gen_random_uuid(),

    region_code text not null,

    island_name text not null,

    region_name text not null,

    total_region integer not null default 0
        check (total_region >= 0),

    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

create index if not exists idx_fasih_regions_code
    on public.fasih_regions(region_code);

create index if not exists idx_fasih_regions_island
    on public.fasih_regions(island_name);


-- =========================================================
-- 6. ASSIGNMENT
-- =========================================================
-- Satu assignment = satu Pencacah + satu Wilayah.
--
-- Pengawas bukan dataset assignment terpisah.
-- Pengawas hanya merupakan petugas yang memonitor assignment
-- milik Pencacah.

create table if not exists public.fasih_assignments (
    id uuid primary key default gen_random_uuid(),

    region_id uuid not null
        references public.fasih_regions(id)
        on delete restrict,

    pencacah_id uuid not null
        references public.fasih_officers(id)
        on delete restrict,

    pengawas_id uuid
        references public.fasih_officers(id)
        on delete set null,

    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),

    constraint fasih_assignment_unique
        unique (pencacah_id, region_id),

    constraint fasih_assignment_different_officers
        check (
            pengawas_id is null
            or pengawas_id <> pencacah_id
        )
);

create index if not exists idx_fasih_assignments_region
    on public.fasih_assignments(region_id);

create index if not exists idx_fasih_assignments_pencacah
    on public.fasih_assignments(pencacah_id);

create index if not exists idx_fasih_assignments_pengawas
    on public.fasih_assignments(pengawas_id);


-- =========================================================
-- 7. STATUS ASSIGNMENT
-- =========================================================

create table if not exists public.fasih_region_status (
    id uuid primary key default gen_random_uuid(),

    assignment_id uuid not null
        references public.fasih_assignments(id)
        on delete cascade,

    approved integer not null default 0
        check (approved >= 0),

    draft integer not null default 0
        check (draft >= 0),

    open integer not null default 0
        check (open >= 0),

    submitted integer not null default 0
        check (submitted >= 0),

    rejected integer not null default 0
        check (rejected >= 0),

    edited_admin integer not null default 0
        check (edited_admin >= 0),

    revoked integer not null default 0
        check (revoked >= 0),

    submitted_respondent integer not null default 0
        check (submitted_respondent >= 0),

    edited_supervisor integer not null default 0
        check (edited_supervisor >= 0),

    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),

    constraint fasih_region_status_assignment_unique
        unique (assignment_id)
);

create index if not exists idx_fasih_status_assignment
    on public.fasih_region_status(assignment_id);


-- =========================================================
-- 8. IMPORT HISTORY
-- =========================================================

create table if not exists public.fasih_imports (
    id uuid primary key default gen_random_uuid(),

    file_name text not null,

    imported_by uuid
        references public.fasih_users(id)
        on delete set null,

    total_rows integer not null default 0
        check (total_rows >= 0),

    success_rows integer not null default 0
        check (success_rows >= 0),

    failed_rows integer not null default 0
        check (failed_rows >= 0),

    status text not null default 'processing'
        check (
            status in (
                'processing',
                'completed',
                'completed_with_errors',
                'failed'
            )
        ),

    error_message text,

    created_at timestamptz not null default now()
);


-- =========================================================
-- 9. IMPORT ERRORS
-- =========================================================

create table if not exists public.fasih_import_errors (
    id uuid primary key default gen_random_uuid(),

    import_id uuid not null
        references public.fasih_imports(id)
        on delete cascade,

    row_number integer not null
        check (row_number > 0),

    error_type text not null,

    error_message text not null,

    raw_data jsonb,

    created_at timestamptz not null default now()
);

create index if not exists idx_fasih_import_errors_import
    on public.fasih_import_errors(import_id);


-- =========================================================
-- 10. ACTIVITY LOG
-- =========================================================

create table if not exists public.fasih_activity_logs (
    id uuid primary key default gen_random_uuid(),

    user_id uuid
        references public.fasih_users(id)
        on delete set null,

    action text not null,

    table_name text not null,

    record_id uuid,

    old_data jsonb,

    new_data jsonb,

    created_at timestamptz not null default now()
);

create index if not exists idx_fasih_logs_user
    on public.fasih_activity_logs(user_id);

create index if not exists idx_fasih_logs_record
    on public.fasih_activity_logs(record_id);

create index if not exists idx_fasih_logs_created
    on public.fasih_activity_logs(created_at);


-- =========================================================
-- 11. TRIGGER updated_at
-- =========================================================

drop trigger if exists fasih_officers_updated_at
on public.fasih_officers;

create trigger fasih_officers_updated_at
before update on public.fasih_officers
for each row
execute function public.fasih_set_updated_at();


drop trigger if exists fasih_users_updated_at
on public.fasih_users;

create trigger fasih_users_updated_at
before update on public.fasih_users
for each row
execute function public.fasih_set_updated_at();


drop trigger if exists fasih_regions_updated_at
on public.fasih_regions;

create trigger fasih_regions_updated_at
before update on public.fasih_regions
for each row
execute function public.fasih_set_updated_at();


drop trigger if exists fasih_assignments_updated_at
on public.fasih_assignments;

create trigger fasih_assignments_updated_at
before update on public.fasih_assignments
for each row
execute function public.fasih_set_updated_at();


drop trigger if exists fasih_region_status_updated_at
on public.fasih_region_status;

create trigger fasih_region_status_updated_at
before update on public.fasih_region_status
for each row
execute function public.fasih_set_updated_at();


-- =========================================================
-- 12. VALIDASI ROLE ASSIGNMENT
-- =========================================================

create or replace function public.fasih_validate_assignment_roles()
returns trigger
language plpgsql
as $$
declare
    v_pencacah_role text;
    v_pengawas_role text;
begin

    -- Pencacah wajib memiliki role pencacah
    select officer_role
    into v_pencacah_role
    from public.fasih_officers
    where id = new.pencacah_id;

    if v_pencacah_role is distinct from 'pencacah' then
        raise exception
        'Petugas pada pencacah_id harus memiliki role pencacah';
    end if;


    -- Pengawas wajib memiliki role pengawas
    if new.pengawas_id is not null then

        select officer_role
        into v_pengawas_role
        from public.fasih_officers
        where id = new.pengawas_id;

        if v_pengawas_role is distinct from 'pengawas' then
            raise exception
            'Petugas pada pengawas_id harus memiliki role pengawas';
        end if;

    end if;

    return new;

end;
$$;


drop trigger if exists fasih_assignment_role_validation
on public.fasih_assignments;

create trigger fasih_assignment_role_validation
before insert or update
on public.fasih_assignments
for each row
execute function public.fasih_validate_assignment_roles();




